{
  "requirement_definitions": [
    {
      "id": "DMSR-1156",
      "title": "Task Conﬁguration",
      "text": "The DMS shall provide software to deﬁne, override components of, and verify the suitability of the conﬁguration for a task."
    },
    {
      "id": "DMSR-7893",
      "title": "Task Speciﬁcation",
      "text": "The DMS shall provide software to deﬁne (and redeﬁne without recompilation) a pipeline task containing a science algorithm, which may in turn consist of the execution of other subtasks."
    },
    {
      "id": "DMSR-5224",
      "title": "Unique Processing Coverage",
      "text": "The DMS shall enable applications to process every record in a table meeting user-speciﬁed criteria exactly once."
    },
    {
      "id": "DMSR-4996",
      "title": "Raw Data Archiving Reliability",
      "text": "The DMS system shall archive all data, including science, wavefront, and guider images and associated metadata, that are presented for archiving by up-stream systems, with a rate of permanent data loss or corruption not to exceed dataLossMax."
    },
    {
      "id": "DMSR-9405",
      "title": "Keep Historical Alert Archive",
      "text": "The DMS shall preserve and keep in an accessible state an alert archive with all issued alerts for a historical record and for false alert analysis."
    },
    {
      "id": "DMSR-7380",
      "title": "Archiving Camera Test Data",
      "text": "The DMS shall be able to archive a designated subset of Camera test data and make it available in an environment matching the data backbone interfaces."
    },
    {
      "id": "DMSR-9728",
      "title": "Un-Archived Data Product Cache",
      "text": "The DMS shall provide low-latency storage for un-archived data products of at least l1CacheLifetime to enable eﬃcient precovery and other Level-1 production measurements."
    },
    {
      "id": "DMSR-9522",
      "title": "Archive Processing Provenance",
      "text": "The Data Management System shall archive all processing provenance associated with archived data products, including relevant data from other subsystems."
    },
    {
      "id": "DMSR-4707",
      "title": "Serve Archived Provenance",
      "text": "The Data Management System shall make the archived provenance data available to science users together with the associated science data products."
    },
    {
      "id": "DMSR-4370",
      "title": "Regenerate Un-archived Data Products",
      "text": "The DMS shall be able to regenerate unarchived data products to within scientiﬁcally reasonable tolerances."
    }
  ],
